/*
 * Generated from the seven approved benchmark component sections in
 * app/globals.css. Run npm run styles:build after editing canonical styles.
 * Page, Lab, documentation, and marketing selectors are deliberately omitted.
 */

button:focus-visible:not(.gummy-button, .gummy-card, .gummy-switch, .gummy-tabs__tab, .gummy-menu__trigger, .gummy-dialog__trigger, .gummy-dialog__close),
input:focus-visible:not(.gummy-input__field, .gummy-field__control, .gummy-checkbox__input, .gummy-radio-item__input) {
  outline: none;
  box-shadow: inset 0 -3px 0 var(--focus-keyline);
  filter: saturate(1.08) brightness(1.015);
}

a:focus-visible:not(.gummy-card) {
  outline: none;
  text-decoration: underline;
  text-decoration-thickness: 2px;
  text-underline-offset: 4px;
}

.gummy-input {
  --input-light: oklch(0.995 0.02 78);
  --input-core: oklch(0.97 0.025 30);
  --input-rim: oklch(0.78 0.07 13);
  --input-depth: oklch(0.69 0.11 8);
  --input-shadow: oklch(0.66 0.16 8 / 0.16);
  --input-shell-light: var(--input-light);
  --input-shell-core: var(--input-core);
  --input-shell-rim: var(--input-rim);
  --input-shell-depth: var(--input-depth);
  --input-plane-light: oklch(0.997 0.012 76 / 0.88);
  --input-plane-core: oklch(0.975 0.024 42 / 0.83);
  --input-label: oklch(0.225 0.068 309);
  --input-muted: oklch(0.46 0.045 309);
  display: grid;
  width: 100%;
  gap: 8px;
  color: var(--input-label);
}

.gummy-input[data-status="error"] {
  --input-light: oklch(0.98 0.04 15);
  --input-core: oklch(0.94 0.06 13);
  --input-rim: var(--fruit-raspberry-rim);
  --input-depth: var(--fruit-raspberry-depth);
  --input-shadow: oklch(0.62 0.25 8 / 0.22);
}

.gummy-input[data-status="success"] {
  --input-light: oklch(0.99 0.04 126);
  --input-core: oklch(0.96 0.07 126);
  --input-rim: var(--fruit-lime-rim);
  --input-depth: var(--fruit-lime-depth);
  --input-shadow: oklch(0.7 0.18 126 / 0.2);
}

.gummy-input[data-status="success"] .gummy-input__control {
  border-color: color-mix(in oklch, var(--fruit-lime-rim) 58%, white);
}

.gummy-input__label-row {
  display: flex;
  min-height: 21px;
  align-items: baseline;
  gap: 8px;
}

.gummy-input__label {
  color: var(--ink);
  font-size: 13px;
  font-weight: 720;
  letter-spacing: -0.01em;
}

.gummy-input__label::after {
  display: inline-block;
  width: 8px;
  height: 6px;
  margin-left: 6px;
  border-radius: 2px 50% 50%;
  background: var(--input-shell-depth);
  content: "";
  opacity: 0;
  transform: scale(0.55) rotate(27deg);
  transition: opacity 140ms ease, transform 180ms cubic-bezier(0.2, 1.4, 0.3, 1);
}

.gummy-input__required,
.gummy-input__read-only {
  color: var(--muted);
  font-family: var(--font-mono), monospace;
  font-size: 9px;
  font-weight: 650;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.gummy-input__control {
  position: relative;
  isolation: isolate;
  display: flex;
  min-height: 58px;
  align-items: center;
  gap: 8px;
  overflow: hidden;
  border: 0;
  border-radius: 32px 27px 31px 25px / 25px 32px 24px 30px;
  background:
    radial-gradient(ellipse 42% 30% at 17% 8%, oklch(1 0 0 / 0.6), transparent 74%),
    radial-gradient(ellipse 58% 92% at 18% 44%, color-mix(in oklch, var(--input-shell-light) 28%, transparent), transparent 78%),
    radial-gradient(ellipse 68% 82% at 94% 105%, color-mix(in oklch, var(--input-shell-depth) 24%, transparent), transparent 76%),
    linear-gradient(137deg, color-mix(in oklch, var(--input-shell-light) 34%, transparent), color-mix(in oklch, var(--input-shell-core) 22%, transparent) 50%, color-mix(in oklch, var(--input-shell-rim) 38%, transparent));
  backdrop-filter: blur(13px) saturate(1.28);
  box-shadow:
    inset 2px 3px 5px oklch(1 0 0 / 0.58),
    inset -7px -8px 13px color-mix(in oklch, var(--input-shell-depth) 17%, transparent),
    0 7px 18px color-mix(in oklch, var(--input-shadow) 23%, transparent);
  padding: 0 20px;
  transition: box-shadow 180ms ease, filter 150ms ease, transform 220ms cubic-bezier(0.2, 1.16, 0.25, 1), border-radius 180ms ease;
}

.gummy-input__control::before {
  position: absolute;
  z-index: -1;
  inset: 6px 45px 6px 6px;
  border: 0;
  border-radius: 24px 18px 22px 20px / 19px 25px 18px 23px;
  background:
    radial-gradient(ellipse 76% 66% at 46% 22%, color-mix(in oklch, var(--input-plane-light) 76%, transparent), transparent 78%),
    linear-gradient(150deg, var(--input-plane-light), var(--input-plane-core));
  box-shadow:
    inset 2px 3px 7px oklch(1 0 0 / 0.42),
    inset -4px -5px 9px color-mix(in oklch, var(--input-shell-depth) 7%, transparent);
  content: "";
  pointer-events: none;
}

.gummy-input__control::after {
  position: absolute;
  z-index: 0;
  top: 1px;
  right: -6px;
  width: 84px;
  height: 56px;
  border-radius: 58% 42% 54% 46% / 48% 43% 57% 52%;
  background:
    radial-gradient(circle at 58% 24%, oklch(1 0 0 / 0.72) 0 4%, transparent 6%),
    radial-gradient(ellipse at 55% 54%, color-mix(in oklch, var(--input-shell-core) 58%, transparent), color-mix(in oklch, var(--input-shell-rim) 52%, transparent) 60%, color-mix(in oklch, var(--input-shell-depth) 30%, transparent) 88%);
  box-shadow:
    inset 3px 4px 6px oklch(1 0 0 / 0.42),
    inset -6px -8px 11px color-mix(in oklch, var(--input-shell-depth) 20%, transparent);
  content: "";
  opacity: 0.72;
  pointer-events: none;
  transform: rotate(1.5deg);
  transition: background 180ms ease, transform 220ms cubic-bezier(0.2, 1.2, 0.25, 1);
}

.gummy-input__field {
  z-index: 1;
  width: 100%;
  min-width: 0;
  min-height: 54px;
  padding: 12px 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--input-label);
  font-size: 16px;
  font-weight: 560;
  line-height: 1.25;
}

.gummy-input__field::placeholder {
  color: oklch(0.58 0.035 309);
  opacity: 1;
}

.gummy-input__adornment {
  position: relative;
  z-index: 1;
  flex: none;
  color: var(--input-muted);
  font-size: 12px;
  font-weight: 620;
  white-space: nowrap;
}

.gummy-input__status-icon {
  position: absolute;
  z-index: 2;
  right: 14px;
  display: grid;
  width: 24px;
  height: 24px;
  flex: none;
  place-items: center;
  border: 0;
  border-radius: 64% 36% 58% 42% / 43% 61% 39% 57%;
  background:
    radial-gradient(circle at 30% 24%, oklch(1 0 0 / 0.58), transparent 54%),
    color-mix(in oklch, var(--input-shell-rim) 64%, transparent);
  box-shadow:
    inset 1px 1px 2px oklch(1 0 0 / 0.48),
    inset -2px -2px 4px color-mix(in oklch, var(--input-shell-depth) 14%, transparent);
  color: oklch(0.2 0.065 309);
  font-size: 13px;
  font-weight: 800;
  transform: rotate(-2deg) scale(1.08);
}

.gummy-input:has(.gummy-input__status-icon) .gummy-input__control { padding-right: 58px; }

.gummy-input__message {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.45;
}

.gummy-input__message--error,
.gummy-input__message--success {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.gummy-input__message-mark {
  width: 7px;
  height: 7px;
  flex: none;
  border-radius: 68% 32% 57% 43% / 41% 64% 36% 59%;
  background: currentColor;
  box-shadow: inset 1px 1px 1px oklch(1 0 0 / 0.46);
  transform: rotate(18deg);
}

.gummy-input__message--error {
  color: oklch(0.43 0.18 12);
  font-weight: 650;
}

.gummy-input__message--success {
  color: oklch(0.38 0.13 130);
  font-weight: 650;
}

:root[data-theme="dark"] .gummy-input__label {
  color: oklch(0.975 0.018 82);
}

:root[data-theme="dark"] .gummy-input {
  --input-label: oklch(0.965 0.02 82);
  --input-muted: oklch(0.76 0.04 311);
}

:root[data-theme="dark"] .gummy-input__field::placeholder {
  color: oklch(0.74 0.035 311);
}

:root[data-theme="dark"] .gummy-input__control {
  box-shadow:
    inset 3px 4px 8px oklch(1 0 0 / 0.25),
    inset -6px -8px 13px color-mix(in oklch, var(--input-shell-depth) 17%, transparent),
    0 9px 22px color-mix(in oklch, var(--input-shadow) 38%, transparent);
}

:root[data-theme="dark"] .gummy-input__control::before {
  background:
    radial-gradient(ellipse 76% 66% at 46% 22%, oklch(1 0 0 / 0.09), transparent 78%),
    color-mix(in oklch, var(--surface-solid) 68%, transparent);
}

:root[data-theme="dark"] .gummy-input[data-status="success"] .gummy-input__control {
  border-color: color-mix(in oklch, var(--fruit-lime-rim) 68%, oklch(1 0 0 / 0.3));
}

:root[data-theme="dark"] .gummy-input__required,
:root[data-theme="dark"] .gummy-input__read-only,
:root[data-theme="dark"] .gummy-input__message:not(.gummy-input__message--error, .gummy-input__message--success) {
  color: oklch(0.72 0.038 311);
}

:root[data-theme="dark"] .gummy-input__message--error {
  color: oklch(0.8 0.14 13);
}

:root[data-theme="dark"] .gummy-input__message--success {
  color: oklch(0.83 0.16 126);
}

.gummy-input[data-filled="true"] .gummy-input__control {
  filter: saturate(1.035);
}

.gummy-input__field:focus-visible {
  outline: none;
  box-shadow: none;
  filter: none;
}

.gummy-input:has(.gummy-input__field:focus-visible) .gummy-input__label::after,
.gummy-input--preview-focus .gummy-input__label::after {
  opacity: 1;
  transform: scale(1) rotate(45deg);
}

.gummy-input:not([data-status="error"], [data-status="success"]):has(.gummy-input__field:focus-visible),
.gummy-input--preview-focus .gummy-input:not([data-status="error"], [data-status="success"]) {
  --input-shell-light: var(--fruit-aqua-light);
  --input-shell-core: color-mix(in oklch, var(--fruit-aqua-core) 54%, transparent);
  --input-shell-rim: color-mix(in oklch, var(--fruit-aqua-rim) 62%, transparent);
  --input-shell-depth: color-mix(in oklch, var(--fruit-aqua-depth) 52%, transparent);
  --input-shadow: oklch(0.62 0.15 215 / 0.13);
}

.gummy-input__control:has(.gummy-input__field:focus-visible),
.gummy-input--preview-focus .gummy-input__control {
  outline: none;
  box-shadow:
    inset 4px 5px 10px oklch(1 0 0 / 0.46),
    inset -7px -9px 14px color-mix(in oklch, var(--input-shell-depth) 18%, transparent),
    0 9px 22px color-mix(in oklch, var(--input-shadow) 46%, transparent);
  filter: saturate(1.06) brightness(1.012);
  transform: translateY(-1px) scaleX(1.012) scaleY(1.035) rotate(-0.25deg);
}

.gummy-input__control:has(.gummy-input__field:focus-visible)::after,
.gummy-input--preview-focus .gummy-input__control::after {
  transform: translateX(2px) scale(1.08, 1.04) rotate(4deg);
}

.gummy-input[data-disabled="true"] {
  opacity: 0.55;
}

.gummy-input[data-disabled="true"] .gummy-input__control {
  box-shadow:
    inset 0 0 0 1px oklch(1 0 0 / 0.22),
    inset 2px 3px 7px oklch(1 0 0 / 0.28);
}

.gummy-input[data-disabled="true"] .gummy-input__field {
  cursor: not-allowed;
}

.gummy-input[data-read-only="true"] .gummy-input__control::before {
  background:
    repeating-linear-gradient(135deg, transparent 0 8px, color-mix(in oklch, var(--input-rim) 7%, transparent) 8px 9px),
    linear-gradient(150deg, var(--input-plane-light), var(--input-plane-core));
}

@media (hover: hover) and (pointer: fine) {
  .gummy-input:not([data-disabled="true"]) .gummy-input__control:hover,
.gummy-input--preview-hover .gummy-input__control {
    filter: saturate(1.06) brightness(1.01);
    transform: translateY(-1px) scaleX(1.006);
  }
}

.gummy-badge {
  --badge-light: oklch(0.995 0.016 79);
  --badge-core: oklch(0.95 0.03 50);
  --badge-rim: oklch(0.75 0.06 30);
  --badge-depth: oklch(0.65 0.075 25);
  --badge-alive-delay: 900ms;
  --badge-label: oklch(0.2 0.065 309);
  position: relative;
  isolation: isolate;
  display: inline-flex;
  width: max-content;
  max-width: 100%;
  min-width: 42px;
  min-height: 42px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  overflow: hidden;
  padding: 9px 15px 10px;
  border: 0;
  border-radius: 23px 14px 19px 12px / 24px 17px 21px 14px;
  background:
    radial-gradient(ellipse 54% 82% at 23% 38%, color-mix(in oklch, var(--badge-light) 82%, transparent) 0 32%, transparent 76%),
    radial-gradient(ellipse 62% 88% at 73% 48%, color-mix(in oklch, var(--badge-core) 74%, transparent) 0 38%, transparent 82%),
    radial-gradient(ellipse 92% 38% at 48% 102%, color-mix(in oklch, var(--badge-depth) 34%, transparent), transparent 72%),
    linear-gradient(137deg, color-mix(in oklch, var(--badge-light) 88%, white), var(--badge-core) 48%, color-mix(in oklch, var(--badge-rim) 84%, var(--badge-core)));
  box-shadow:
    inset 2px 2px 3px oklch(1 0 0 / 0.5),
    inset 7px 8px 13px oklch(1 0 0 / 0.18),
    inset -8px -9px 14px color-mix(in oklch, var(--badge-depth) 27%, transparent),
    inset 0 -6px 10px color-mix(in oklch, var(--badge-depth) 21%, transparent);
  color: var(--badge-label);
  font-size: 12px;
  font-weight: 735;
  letter-spacing: -0.018em;
  line-height: 1.2;
  transform: rotate(-0.35deg) skewX(-0.25deg);
  transform-origin: 47% 56%;
  vertical-align: middle;
  will-change: transform, filter, border-radius;
}

.gummy-badge[data-motion="alive"] {
  animation:
    gummy-badge-settle 760ms cubic-bezier(0.2, 1.24, 0.28, 1) both,
    gummy-badge-alive 4.9s ease-in-out var(--badge-alive-delay) infinite;
}

.gummy-badge[data-motion="settle"] {
  animation: gummy-badge-settle 760ms cubic-bezier(0.2, 1.24, 0.28, 1) both;
}

.gummy-badge[data-motion="alive"] :is(.gummy-badge__dot, .gummy-badge__icon, .gummy-badge__label) {
  animation:
    gummy-badge-content-settle 760ms cubic-bezier(0.2, 1.24, 0.28, 1) both,
    gummy-badge-content-alive 4.9s ease-in-out var(--badge-alive-delay) infinite;
}

.gummy-badge[data-motion="settle"] :is(.gummy-badge__dot, .gummy-badge__icon, .gummy-badge__label) {
  animation: gummy-badge-content-settle 760ms cubic-bezier(0.2, 1.24, 0.28, 1) both;
}

.gummy-badge::before {
  position: absolute;
  z-index: 0;
  top: 11%;
  left: 13%;
  width: 27%;
  height: 18%;
  border-radius: 64% 36% 58% 42% / 58% 68% 32% 42%;
  background: radial-gradient(ellipse at 42% 50%, oklch(1 0 0 / 0.92) 0 18%, oklch(1 0 0 / 0.38) 45%, transparent 74%);
  content: "";
  pointer-events: none;
  transform: rotate(-13deg);
  transform-origin: center;
}

.gummy-badge[data-motion="alive"]::before {
  animation:
    gummy-badge-highlight-settle 760ms cubic-bezier(0.2, 1.24, 0.28, 1) both,
    gummy-badge-highlight-alive 4.9s ease-in-out var(--badge-alive-delay) infinite;
}

.gummy-badge[data-motion="settle"]::before {
  animation: gummy-badge-highlight-settle 760ms cubic-bezier(0.2, 1.24, 0.28, 1) both;
}

.gummy-badge::after {
  position: absolute;
  z-index: 0;
  top: 12%;
  left: 19%;
  width: 68%;
  height: 74%;
  border-radius: 43% 57% 48% 52% / 59% 43% 57% 41%;
  background:
    radial-gradient(ellipse at 28% 28%, color-mix(in oklch, var(--badge-light) 46%, transparent), transparent 46%),
    radial-gradient(ellipse at 72% 68%, color-mix(in oklch, var(--badge-depth) 18%, transparent), transparent 64%);
  content: "";
  opacity: 0.72;
  pointer-events: none;
  transform: rotate(-7deg);
  transform-origin: center;
}

.gummy-badge[data-motion="alive"]::after {
  animation:
    gummy-badge-cloud-settle 760ms cubic-bezier(0.2, 1.24, 0.28, 1) both,
    gummy-badge-cloud-alive 4.9s ease-in-out var(--badge-alive-delay) infinite;
}

.gummy-badge[data-motion="settle"]::after {
  animation: gummy-badge-cloud-settle 760ms cubic-bezier(0.2, 1.24, 0.28, 1) both;
}

@keyframes gummy-badge-settle {
  0% {
    border-radius: 23px 14px 19px 12px / 24px 17px 21px 14px;
    filter: saturate(1) brightness(1);
    transform: rotate(-0.35deg) scale(1) skewX(-0.25deg);
  }
  18% {
    border-radius: 18px 16px 23px 12px / 24px 16px 19px 18px;
    filter: saturate(1.05) brightness(1.018);
    transform: translate(-1px, -1px) rotate(-4.2deg) scaleX(0.97) scaleY(1.055) skewX(-1.2deg);
  }
  40% {
    border-radius: 16px 22px 17px 20px / 15px 17px 16px 15px;
    filter: saturate(1.1) brightness(1.01);
    transform: translateY(2px) rotate(0.4deg) scaleX(1.13) scaleY(0.84) skewX(0.7deg);
  }
  58% {
    border-radius: 20px 13px 21px 16px / 23px 20px 18px 17px;
    filter: saturate(1.055) brightness(1.015);
    transform: translate(1px, -1px) rotate(2.4deg) scaleX(0.965) scaleY(1.07) skewX(0.8deg);
  }
  75% {
    transform: rotate(-1.4deg) scaleX(1.025) scaleY(0.985) skewX(-0.5deg);
  }
  100% {
    border-radius: 23px 14px 19px 12px / 24px 17px 21px 14px;
    filter: none;
    transform: rotate(-0.35deg) scale(1) skewX(-0.25deg);
  }
}

@keyframes gummy-badge-highlight-settle {
  0% { transform: translate(0, 0) scale(1) rotate(-13deg); }
  18% { transform: translate(10%, -2%) scaleX(0.84) scaleY(1.2) rotate(-18deg); }
  40% { transform: translate(-10%, 11%) scaleX(1.24) scaleY(0.7) rotate(-4deg); }
  58% { transform: translate(8%, -4%) scaleX(0.88) scaleY(1.14) rotate(-16deg); }
  75% { transform: translate(-3%, 2%) scaleX(1.05) scaleY(0.94) rotate(-10deg); }
  100% { transform: translate(0, 0) scale(1) rotate(-13deg); }
}

@keyframes gummy-badge-cloud-settle {
  0% { opacity: 0.72; transform: translate(0, 0) scale(1) rotate(-7deg); }
  18% { opacity: 0.8; transform: translate(-7%, -3%) scaleX(0.9) scaleY(1.14) rotate(-11deg); }
  40% { opacity: 0.58; transform: translate(9%, 8%) scaleX(1.16) scaleY(0.76) rotate(0deg); }
  58% { opacity: 0.76; transform: translate(-4%, -3%) scaleX(0.92) scaleY(1.1) rotate(-9deg); }
  75% { opacity: 0.68; transform: translate(2%, 1%) scaleX(1.04) scaleY(0.96) rotate(-5deg); }
  100% { opacity: 0.72; transform: translate(0, 0) scale(1) rotate(-7deg); }
}

@keyframes gummy-badge-content-settle {
  0%, 100% { transform: none; }
  18% { transform: scaleX(1.025) scaleY(0.96); }
  40% { transform: scaleX(0.9) scaleY(1.12); }
  58% { transform: scaleX(1.025) scaleY(0.95); }
  75% { transform: scaleX(0.985) scaleY(1.01); }
}

@keyframes gummy-badge-alive {
  0%, 67%, 100% {
    border-radius: 23px 14px 19px 12px / 24px 17px 21px 14px;
    filter: none;
    transform: rotate(-0.35deg) scale(1) skewX(-0.25deg);
  }
  75% {
    border-radius: 18px 16px 23px 12px / 24px 16px 19px 18px;
    filter: saturate(1.045) brightness(1.012);
    transform: translate(-1px, -1px) rotate(-3.2deg) scaleX(0.98) scaleY(1.045) skewX(-0.9deg);
  }
  84% {
    border-radius: 16px 22px 17px 20px / 15px 17px 16px 15px;
    filter: saturate(1.075);
    transform: translateY(1px) rotate(0.5deg) scaleX(1.08) scaleY(0.91) skewX(0.55deg);
  }
  91% {
    border-radius: 20px 13px 21px 16px / 23px 20px 18px 17px;
    filter: saturate(1.03);
    transform: translate(0.5px, -0.5px) rotate(1.8deg) scaleX(0.98) scaleY(1.035) skewX(0.4deg);
  }
  96% { transform: rotate(-1deg) scaleX(1.015) scaleY(0.99); }
}

@keyframes gummy-badge-highlight-alive {
  0%, 67%, 100% { transform: translate(0, 0) scale(1) rotate(-13deg); }
  75% { transform: translate(8%, -2%) scaleX(0.88) scaleY(1.15) rotate(-17deg); }
  84% { transform: translate(-8%, 8%) scaleX(1.18) scaleY(0.78) rotate(-5deg); }
  91% { transform: translate(6%, -3%) scaleX(0.92) scaleY(1.08) rotate(-15deg); }
  96% { transform: translate(-2%, 1%) scaleX(1.03) rotate(-11deg); }
}

@keyframes gummy-badge-cloud-alive {
  0%, 67%, 100% { opacity: 0.72; transform: translate(0, 0) scale(1) rotate(-7deg); }
  75% { opacity: 0.79; transform: translate(-5%, -3%) scaleX(0.92) scaleY(1.1) rotate(-10deg); }
  84% { opacity: 0.6; transform: translate(7%, 7%) scaleX(1.12) scaleY(0.82) rotate(-1deg); }
  91% { opacity: 0.75; transform: translate(-3%, -2%) scaleX(0.95) scaleY(1.07) rotate(-9deg); }
  96% { opacity: 0.69; transform: translate(1%, 1%) scale(1.02) rotate(-6deg); }
}

@keyframes gummy-badge-content-alive {
  0%, 67%, 100% { transform: none; }
  75% { transform: scaleX(1.015) scaleY(0.97); }
  84% { transform: scaleX(0.93) scaleY(1.075); }
  91% { transform: scaleX(1.015) scaleY(0.975); }
  96% { transform: scaleX(0.99) scaleY(1.006); }
}

.gummy-badge[data-variant="primary"] {
  --badge-light: var(--fruit-raspberry-light);
  --badge-core: var(--fruit-raspberry-core);
  --badge-rim: var(--fruit-raspberry-rim);
  --badge-depth: var(--fruit-raspberry-depth);
}

.gummy-badge[data-variant="secondary"] {
  --badge-light: var(--fruit-grape-light);
  --badge-core: var(--fruit-grape-core);
  --badge-rim: var(--fruit-grape-rim);
  --badge-depth: var(--fruit-grape-depth);
}

.gummy-badge[data-variant="success"] {
  --badge-light: var(--fruit-lime-light);
  --badge-core: var(--fruit-lime-core);
  --badge-rim: var(--fruit-lime-rim);
  --badge-depth: var(--fruit-lime-depth);
}

.gummy-badge[data-variant="warning"] {
  --badge-light: var(--fruit-tangerine-light);
  --badge-core: var(--fruit-tangerine-core);
  --badge-rim: var(--fruit-tangerine-rim);
  --badge-depth: var(--fruit-tangerine-depth);
}

.gummy-badge[data-variant="info"] {
  --badge-light: var(--fruit-aqua-light);
  --badge-core: var(--fruit-aqua-core);
  --badge-rim: var(--fruit-aqua-rim);
  --badge-depth: var(--fruit-aqua-depth);
}

.gummy-badge[data-finish="translucent"] {
  background:
    radial-gradient(ellipse 42% 30% at 25% 15%, oklch(1 0 0 / 0.58), transparent 74%),
    radial-gradient(ellipse 62% 88% at 26% 44%, color-mix(in oklch, var(--badge-light) 19%, transparent) 0 34%, transparent 78%),
    radial-gradient(ellipse 78% 54% at 74% 88%, color-mix(in oklch, var(--badge-depth) 11%, transparent), transparent 76%),
    linear-gradient(137deg, color-mix(in oklch, var(--badge-light) 16%, transparent), color-mix(in oklch, var(--badge-core) 10%, transparent) 48%, color-mix(in oklch, var(--badge-rim) 27%, transparent));
  backdrop-filter: blur(8px) saturate(1.28);
  box-shadow:
    inset 0 0 0 1.5px oklch(1 0 0 / 0.34),
    inset 2px 2px 4px oklch(1 0 0 / 0.52),
    inset 7px 8px 13px oklch(1 0 0 / 0.13),
    inset -8px -9px 14px color-mix(in oklch, var(--badge-depth) 13%, transparent);
  filter: saturate(1.03);
}

.gummy-badge[data-finish="translucent"]::before {
  width: 31%;
  height: 21%;
  opacity: 0.88;
}

.gummy-badge[data-finish="translucent"]::after {
  opacity: 0.54;
}

:root[data-theme="dark"] .gummy-badge[data-finish="translucent"] {
  --badge-label: oklch(0.965 0.022 82);
}

:root[data-theme="dark"] .gummy-badge[data-finish="translucent"] .gummy-badge__label {
  text-shadow: 0 1px 2px oklch(0.13 0.045 309 / 0.68);
}

:root[data-theme="dark"] .gummy-badge[data-finish="translucent"] .gummy-badge__icon {
  background: oklch(1 0 0 / 0.18);
  box-shadow: inset 1px 1px 2px oklch(1 0 0 / 0.32);
  color: var(--badge-label);
}

.gummy-badge__dot {
  position: relative;
  z-index: 1;
  width: 8px;
  height: 8px;
  flex: none;
  border-radius: 58% 42% 62% 38% / 46% 59% 41% 54%;
  background: var(--badge-depth);
  box-shadow: inset 1px 1px 2px color-mix(in oklch, var(--badge-light) 56%, transparent);
}

.gummy-badge__icon {
  position: relative;
  z-index: 1;
  display: grid;
  width: 17px;
  height: 17px;
  flex: none;
  place-items: center;
  border: 0;
  border-radius: 60% 40% 55% 45% / 45% 58% 42% 55%;
  background: color-mix(in oklch, var(--badge-depth) 24%, transparent);
  box-shadow: inset 1px 1px 2px color-mix(in oklch, var(--badge-light) 42%, transparent);
  font-family: var(--font-mono), monospace;
  font-size: 9px;
}

.gummy-badge__label {
  position: relative;
  z-index: 1;
  min-width: 0;
  overflow-wrap: normal;
  text-shadow: 0 1px 0 oklch(1 0 0 / 0.2);
  white-space: nowrap;
}

.gummy-card {
  --card-light: oklch(0.995 0.025 63);
  --card-core: oklch(0.93 0.06 42);
  --card-rim: oklch(0.8 0.1 27);
  --card-depth: oklch(0.65 0.11 20);
  --card-frame-light: oklch(0.995 0.024 67 / 0.56);
  --card-frame-core: oklch(0.94 0.058 43 / 0.35);
  --card-frame-rim: oklch(0.79 0.095 28 / 0.39);
  --card-frame-depth: oklch(0.64 0.11 20 / 0.24);
  --card-frame-shadow: oklch(0.62 0.11 25 / 0.065);
  --card-label: oklch(0.225 0.068 309);
  --card-muted: oklch(0.43 0.05 309);
  --card-plane-light: oklch(0.997 0.011 72 / 0.94);
  --card-plane-core: oklch(0.98 0.022 47 / 0.91);
  --card-icon-mark: var(--fruit-raspberry-core);
  position: relative;
  isolation: isolate;
  display: block;
  width: 100%;
  overflow: visible;
  min-height: 252px;
  padding: 24px 31px 25px;
  border: 0;
  border-radius: 38px;
  background: transparent;
  box-shadow: none;
  color: var(--card-label);
  text-align: left;
  transition: transform 260ms cubic-bezier(0.2, 0.9, 0.25, 1), filter 180ms ease;
}

.gummy-card__frame {
  position: absolute;
  z-index: 0;
  inset: -5px -7px -8px -6px;
  width: calc(100% + 13px);
  height: calc(100% + 13px);
  overflow: visible;
  pointer-events: none;
  transform-origin: 49% 52%;
  transition: filter 240ms ease, transform 420ms cubic-bezier(0.2, 0.9, 0.25, 1);
}

.gummy-card__frame-shadow {
  fill: var(--card-frame-shadow);
  opacity: 0.5;
  transform: translateY(4px) scale(0.988);
  transform-origin: center;
}

.gummy-card__frame-shell,
.gummy-card__frame-reservoir {
  transition: fill 240ms ease, opacity 240ms ease, transform 420ms cubic-bezier(0.2, 0.9, 0.25, 1);
}

.gummy-card__frame-shell { opacity: 0.76; }
.gummy-card__frame-plane { opacity: 0.96; }

.gummy-card__frame-reservoir {
  opacity: 0.42;
  transform-origin: 88% 86%;
}

.gummy-card__frame-meniscus {
  fill: none;
  vector-effect: non-scaling-stroke;
}

.gummy-card__frame-meniscus--outer {
  stroke: color-mix(in oklch, var(--card-frame-rim) 44%, white);
  stroke-width: 3.1;
  opacity: 0.68;
}

.gummy-card__frame-meniscus--inner {
  stroke: color-mix(in oklch, var(--card-frame-depth) 24%, white);
  stroke-width: 1.55;
  opacity: 0.66;
}

.gummy-card__frame-glint,
.gummy-card__reservoir-glint,
.gummy-card__icon-well {
  fill: none;
  stroke: oklch(1 0 0 / 0.82);
  stroke-linecap: round;
  vector-effect: non-scaling-stroke;
}

.gummy-card__frame-glint {
  stroke-width: 3;
  opacity: 0.88;
}

.gummy-card__reservoir-glint {
  stroke-width: 2.5;
  opacity: 0.76;
}

.gummy-card__icon-well {
  stroke: color-mix(in oklch, var(--card-frame-rim) 26%, white);
  stroke-width: 1.9;
  opacity: 0.74;
}

:root[data-theme="dark"] .gummy-card {
  --card-frame-light: oklch(0.96 0.065 50 / 0.36);
  --card-frame-core: oklch(0.78 0.11 27 / 0.36);
  --card-frame-rim: oklch(0.62 0.14 16 / 0.38);
  --card-frame-depth: oklch(0.45 0.11 10 / 0.3);
  --card-frame-shadow: oklch(0.1 0.045 309 / 0.24);
  --card-plane-light: oklch(0.985 0.016 72 / 0.86);
  --card-plane-core: oklch(0.95 0.029 47 / 0.82);
}

:root[data-theme="dark"] .gummy-card__frame-shell {
  opacity: 0.8;
}

:root[data-theme="dark"] .gummy-card__frame-plane {
  opacity: 0.92;
}

:root[data-theme="dark"] .gummy-card__frame-meniscus--outer {
  stroke: color-mix(in oklch, var(--card-frame-rim) 74%, oklch(1 0 0 / 0.25));
  opacity: 0.64;
}

:root[data-theme="dark"] .gummy-card__frame-meniscus--inner {
  stroke: color-mix(in oklch, var(--card-frame-depth) 70%, oklch(1 0 0 / 0.2));
  opacity: 0.58;
}

:root[data-theme="dark"] .gummy-card__frame-glint,
:root[data-theme="dark"] .gummy-card__reservoir-glint {
  stroke: oklch(1 0 0 / 0.58);
}

:root[data-theme="dark"] .gummy-card__icon-well {
  stroke: color-mix(in oklch, var(--card-frame-rim) 68%, oklch(1 0 0 / 0.24));
  opacity: 0.66;
}

.gummy-card > * {
  position: relative;
  z-index: 1;
}

.gummy-card > .gummy-card__frame {
  position: absolute;
  z-index: 0;
}

button.gummy-card {
  appearance: none;
  font: inherit;
}

.gummy-card--interactive {
  min-height: 44px;
  cursor: pointer;
  touch-action: manipulation;
}

button.gummy-card {
  padding: 24px 31px 25px;
}

.gummy-card[data-elevation="elevated"] {
  --card-frame-core: oklch(0.925 0.068 43 / 0.38);
  --card-frame-rim: oklch(0.76 0.105 27 / 0.4);
  --card-frame-shadow: oklch(0.59 0.1 25 / 0.09);
  transform: translateY(-5px) rotate(-0.12deg);
}

.gummy-card[data-elevation="elevated"] .gummy-card__frame {
  filter: saturate(1.08);
  transform: scaleX(1.006) scaleY(1.015);
}

.gummy-card[data-elevation="elevated"] .gummy-card__frame-shadow {
  opacity: 0.92;
  transform: translateY(10px) scale(0.982);
}

.gummy-card[data-selected="true"] {
  --card-light: var(--fruit-raspberry-light);
  --card-core: var(--fruit-raspberry-core);
  --card-rim: var(--fruit-raspberry-rim);
  --card-depth: var(--fruit-raspberry-depth);
  --card-frame-light: color-mix(in oklch, var(--fruit-raspberry-light) 44%, transparent);
  --card-frame-core: color-mix(in oklch, var(--fruit-raspberry-core) 38%, transparent);
  --card-frame-rim: color-mix(in oklch, var(--fruit-raspberry-rim) 44%, transparent);
  --card-frame-depth: color-mix(in oklch, var(--fruit-raspberry-depth) 34%, transparent);
  --card-frame-shadow: color-mix(in oklch, var(--fruit-raspberry-depth) 9%, transparent);
  --card-plane-light: oklch(0.997 0.014 22 / 0.94);
  --card-plane-core: oklch(0.985 0.024 18 / 0.92);
  --card-icon-mark: oklch(0.995 0.008 25);
}

.gummy-card[data-selected="true"] .gummy-card__frame {
  filter: saturate(1.1);
}

:root[data-theme="dark"] .gummy-card[data-selected="true"] {
  --card-frame-light: oklch(0.94 0.105 6 / 0.48);
  --card-frame-core: oklch(0.76 0.205 8 / 0.5);
  --card-frame-rim: oklch(0.61 0.245 8 / 0.5);
  --card-frame-depth: oklch(0.46 0.19 9 / 0.4);
  --card-frame-shadow: oklch(0.45 0.19 8 / 0.16);
  --card-plane-light: oklch(0.98 0.026 18 / 0.88);
  --card-plane-core: oklch(0.94 0.052 12 / 0.84);
}

:root[data-theme="dark"] .gummy-card[data-elevation="elevated"]:not([data-selected="true"]) {
  --card-frame-core: oklch(0.76 0.125 25 / 0.42);
  --card-frame-rim: oklch(0.59 0.155 14 / 0.44);
  --card-frame-shadow: oklch(0.09 0.045 309 / 0.3);
}

.gummy-card--interactive:focus-visible,
.gummy-card--preview-focus {
  --card-frame-light: color-mix(in oklch, var(--fruit-aqua-light) 46%, transparent);
  --card-frame-core: color-mix(in oklch, var(--fruit-aqua-core) 38%, transparent);
  --card-frame-rim: color-mix(in oklch, var(--fruit-aqua-rim) 43%, transparent);
  --card-frame-depth: color-mix(in oklch, var(--fruit-aqua-depth) 33%, transparent);
  --card-frame-shadow: color-mix(in oklch, var(--fruit-aqua-depth) 8%, transparent);
  --card-plane-light: oklch(0.997 0.011 72 / 0.94);
  --card-plane-core: oklch(0.985 0.018 62 / 0.92);
  outline: none;
  filter: none;
  transform: translateY(-5px) scaleX(1.003) scaleY(1.006);
}

.gummy-card--interactive:focus-visible .gummy-card__frame,
.gummy-card--preview-focus .gummy-card__frame {
  animation: gummy-card-svg-focus 720ms cubic-bezier(0.2, 1.2, 0.28, 1) both;
  filter: saturate(1.08);
}

.gummy-card--interactive:focus-visible .gummy-card__frame-reservoir,
.gummy-card--preview-focus .gummy-card__frame-reservoir {
  animation: gummy-card-svg-reservoir 720ms cubic-bezier(0.2, 1.2, 0.28, 1) both;
}

.gummy-card--interactive:focus-visible .gummy-card__title::after,
.gummy-card--preview-focus .gummy-card__title::after {
  display: inline-block;
  width: 8px;
  height: 6px;
  margin-left: 7px;
  border-radius: 67% 33% 58% 42% / 42% 62% 38% 58%;
  background: var(--card-frame-depth);
  box-shadow: inset 1px 1px 1px oklch(1 0 0 / 0.54);
  content: "";
  transform: rotate(24deg);
  vertical-align: 0.15em;
}

:root[data-theme="dark"] .gummy-card--interactive:focus-visible,
:root[data-theme="dark"] .gummy-card--preview-focus {
  --card-frame-light: oklch(0.94 0.09 204 / 0.46);
  --card-frame-core: oklch(0.8 0.15 207 / 0.48);
  --card-frame-rim: oklch(0.65 0.17 218 / 0.48);
  --card-frame-depth: oklch(0.49 0.14 226 / 0.38);
  --card-plane-light: oklch(0.98 0.018 76 / 0.88);
  --card-plane-core: oklch(0.94 0.035 198 / 0.84);
}

@media (hover: hover) and (pointer: fine) {
  .gummy-card--interactive:not(.gummy-card--preview-focus):hover {
    --card-frame-light: color-mix(in oklch, var(--fruit-aqua-light) 28%, oklch(0.995 0.024 67 / 0.5));
    --card-frame-core: color-mix(in oklch, var(--fruit-aqua-core) 22%, oklch(0.94 0.058 43 / 0.42));
    --card-frame-rim: color-mix(in oklch, var(--fruit-aqua-rim) 24%, oklch(0.79 0.095 28 / 0.4));
    filter: none;
    transform: translateY(-4px) rotate(-0.06deg);
  }

  .gummy-card--interactive:not(.gummy-card--preview-focus):hover .gummy-card__frame {
    filter: saturate(1.04);
    transform: scaleX(1.003) scaleY(1.008);
  }
}

.gummy-card--interactive:active {
  transform: translateY(1px) scaleX(1.007) scaleY(0.988);
}

@keyframes gummy-card-svg-focus {
  0% { transform: scale(1); }
  32% { transform: translate(-1px, -2px) scaleX(1.012) scaleY(1.024) rotate(-0.35deg); }
  58% { transform: translate(1px, 0) scaleX(0.998) scaleY(1.006) rotate(0.16deg); }
  78% { transform: translate(0, -1px) scaleX(1.005) scaleY(1.014) rotate(-0.1deg); }
  100% { transform: scaleX(1.003) scaleY(1.008); }
}

@keyframes gummy-card-svg-reservoir {
  0% { transform: scale(1); }
  32% { transform: translate(4px, 2px) scaleX(1.08) scaleY(1.12) rotate(2deg); }
  58% { transform: translate(-1px, -1px) scaleX(0.985) scaleY(1.01) rotate(-1deg); }
  78% { transform: translate(2px, 1px) scale(1.04); }
  100% { transform: translate(1px, 1px) scale(1.025); }
}

.gummy-card__header {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  min-height: 86px;
  padding: 0 10px 10px 0;
}

.gummy-card__header > :last-child {
  min-width: 0;
  padding-top: 17px;
}

.gummy-card__title {
  margin: 0;
  color: var(--card-label);
  font-family: var(--font-display), sans-serif;
  font-size: 21px;
  font-weight: 770;
  letter-spacing: -0.034em;
  line-height: 1.15;
}

.gummy-card__description {
  margin: 6px 0 0;
  color: var(--card-muted);
  font-size: 11.5px;
  line-height: 1.45;
}

.gummy-card__content {
  padding: 15px 4px 17px;
  border-top: 1px solid color-mix(in oklch, var(--card-frame-rim) 19%, transparent);
  border-bottom: 1px solid color-mix(in oklch, var(--card-frame-rim) 19%, transparent);
  color: var(--card-muted);
  font-size: 13px;
}

.gummy-card__footer {
  display: flex;
  min-height: 45px;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 5px 0;
  border-top: 0;
  color: var(--card-muted);
  font-size: 11px;
}

.gummy-card__icon {
  display: grid;
  width: 86px;
  height: 86px;
  flex: none;
  place-items: center;
  border: 0;
  background: transparent;
  box-shadow: none;
  transform: translate(6px, 6px) rotate(-1.5deg);
  transition: background 220ms ease, transform 300ms cubic-bezier(0.2, 0.9, 0.25, 1);
}

.gummy-card__icon svg {
  width: 40px;
  height: 29px;
  overflow: visible;
}

.gummy-card__icon path {
  fill: none;
  stroke: var(--card-icon-mark);
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 4.8px;
  filter:
    drop-shadow(0 1px 0 oklch(1 0 0 / 0.9))
    drop-shadow(0 0 5px color-mix(in oklch, var(--card-icon-mark) 26%, transparent));
}

.gummy-card--interactive:focus-visible .gummy-card__icon,
.gummy-card--preview-focus .gummy-card__icon {
  transform: translate(5px, 5px) rotate(-3deg) scale(1.035);
}

.gummy-switch-field {
  display: inline-flex;
  align-items: flex-start;
  gap: 15px;
  max-width: 360px;
}

.gummy-switch-field__copy {
  display: grid;
  gap: 3px;
  padding-top: 1px;
}

.gummy-switch-field__copy label {
  color: var(--ink);
  cursor: pointer;
  font-size: 14px;
  font-weight: 680;
  line-height: 1.25;
}

.gummy-switch-field__copy p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.4;
}

.gummy-switch {
  position: relative;
  flex: 0 0 auto;
  width: 78px;
  min-width: 78px;
  height: 44px;
  min-height: 44px;
  overflow: hidden;
  padding: 4px;
  border: 0;
  border-radius: 20px 25px 22px 18px / 18px 21px 23px 25px;
  outline: none;
  background:
    linear-gradient(148deg, oklch(1 0 0 / 0.74) 1%, transparent 27%),
    radial-gradient(ellipse at 74% 78%, var(--fruit-grape-core), transparent 46%),
    color-mix(in oklch, var(--fruit-grape-light) 54%, var(--surface));
  box-shadow:
    inset 0 1px 0 oklch(1 0 0 / 0.86),
    inset 0 -5px 10px color-mix(in oklch, var(--fruit-grape-depth) 28%, transparent),
    inset 0 0 0 1px color-mix(in oklch, var(--fruit-grape-rim) 38%, transparent);
  cursor: pointer;
  touch-action: manipulation;
  transition: filter 160ms ease, transform 220ms cubic-bezier(0.2, 0.9, 0.25, 1), background 220ms ease, box-shadow 220ms ease;
}

.gummy-switch::before {
  position: absolute;
  inset: 3px 11px 24px 13px;
  border-radius: 999px;
  background: linear-gradient(90deg, oklch(1 0 0 / 0.68), oklch(1 0 0 / 0.08));
  content: "";
  pointer-events: none;
  transform: rotate(-3deg);
}

.gummy-switch__pool {
  position: absolute;
  right: 6px;
  bottom: 4px;
  width: 27px;
  height: 15px;
  border-radius: 56% 44% 62% 38%;
  background: color-mix(in oklch, var(--fruit-grape-rim) 38%, transparent);
  filter: blur(3px);
  opacity: 0.75;
  transition: background 220ms ease, opacity 220ms ease, transform 240ms cubic-bezier(0.2, 0.9, 0.25, 1);
}

.gummy-switch__thumb {
  position: relative;
  z-index: 1;
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  border-radius: 48% 52% 44% 56% / 52% 44% 56% 48%;
  background:
    radial-gradient(circle at 32% 25%, oklch(1 0 0 / 0.76) 0 8%, transparent 10%),
    linear-gradient(145deg, var(--fruit-raspberry-light), var(--fruit-raspberry-core) 58%, var(--fruit-raspberry-rim));
  box-shadow:
    inset 1px 2px 3px oklch(1 0 0 / 0.78),
    inset -3px -5px 8px color-mix(in oklch, var(--fruit-raspberry-depth) 40%, transparent),
    1px 2px 4px color-mix(in oklch, var(--fruit-grape-depth) 20%, transparent);
  transition: translate 260ms cubic-bezier(0.2, 1.35, 0.35, 1), transform 220ms cubic-bezier(0.2, 1.35, 0.35, 1), background 220ms ease;
}

.gummy-switch__thumb > span {
  width: 12px;
  height: 5px;
