}

.gummy-menu__item[data-tone="danger"] .gummy-menu__item-icon,
.gummy-menu__item[data-tone="danger"] { color: color-mix(in oklch, var(--fruit-raspberry-depth) 74%, var(--ink)); }

.gummy-menu__item[data-tone="danger"][data-highlighted] .gummy-menu__item-tide {
  background: linear-gradient(90deg, color-mix(in oklch, var(--fruit-raspberry-core) 48%, transparent), color-mix(in oklch, var(--fruit-raspberry-light) 32%, transparent), transparent);
}

.gummy-menu-demo-icon {
  position: relative;
  display: block;
  width: 15px;
  height: 15px;
}

.gummy-menu-demo-icon[data-icon="clock"],
.gummy-menu-demo-icon[data-icon="history"] {
  border: 1.5px solid currentColor;
  border-radius: 50%;
}

.gummy-menu-demo-icon[data-icon="clock"]::before,
.gummy-menu-demo-icon[data-icon="history"]::before {
  position: absolute;
  top: 3px;
  left: 6px;
  width: 1.5px;
  height: 5px;
  border-radius: 999px;
  background: currentColor;
  content: "";
  transform-origin: bottom;
  transform: rotate(-16deg);
}

.gummy-menu-demo-icon[data-icon="history"]::after {
  position: absolute;
  top: -2px;
  left: -2px;
  width: 5px;
  height: 5px;
  border-top: 1.5px solid currentColor;
  border-left: 1.5px solid currentColor;
  content: "";
  transform: rotate(-18deg);
}

.gummy-menu-demo-icon[data-icon="trend"]::before {
  position: absolute;
  top: 7px;
  left: 1px;
  width: 13px;
  height: 8px;
  border-top: 1.6px solid currentColor;
  border-right: 1.6px solid currentColor;
  content: "";
  transform: skewY(-30deg) rotate(-4deg);
}

.gummy-menu-demo-icon[data-icon="archive"] {
  border: 1.5px solid currentColor;
  border-radius: 3px 3px 4px 4px;
}

.gummy-menu-demo-icon[data-icon="archive"]::before {
  position: absolute;
  top: 3px;
  right: -2px;
  left: -2px;
  height: 1.5px;
  background: currentColor;
  content: "";
}

.gummy-menu-demo-icon[data-icon="archive"]::after {
  position: absolute;
  top: 7px;
  left: 4px;
  width: 5px;
  height: 1.5px;
  border-radius: 999px;
  background: currentColor;
  content: "";
}

.gummy-menu__separator {
  height: 1px;
  margin: 8px 14px;
  background: linear-gradient(90deg, color-mix(in oklch, var(--line-strong) 34%, transparent), transparent 88%);
}

.gummy-dialog__backdrop {
  position: fixed;
  z-index: 90;
  inset: 0;
  min-height: 100dvh;
  background:
    radial-gradient(circle at 50% 45%, oklch(0.43 0.12 310 / 0.2), transparent 34rem),
    oklch(0.12 0.055 311 / 0.64);
  backdrop-filter: blur(8px) saturate(0.82);
  transition: opacity 180ms ease;
}

.gummy-dialog__backdrop[data-starting-style],
.gummy-dialog__backdrop[data-ending-style] { opacity: 0; }

.gummy-dialog__viewport {
  position: fixed;
  z-index: 91;
  inset: 0;
  display: grid;
  min-height: 100dvh;
  place-items: center;
  overflow-y: auto;
  padding: 24px;
}

.gummy-dialog__popup {
  position: relative;
  width: min(100%, 500px);
  isolation: isolate;
  padding: 13px 14px 15px 13px;
  border: 0;
  border-radius: 38px 31px 43px 29px / 31px 42px 28px 39px;
  outline: none;
  background:
    radial-gradient(circle at 12% 8%, oklch(1 0 0 / 0.72) 0 2%, transparent 4%),
    radial-gradient(ellipse at 6% 4%, color-mix(in oklch, var(--fruit-raspberry-core) 72%, transparent), transparent 30%),
    radial-gradient(ellipse at 94% 94%, color-mix(in oklch, var(--fruit-raspberry-rim) 70%, transparent), transparent 36%),
    linear-gradient(148deg, oklch(1 0 0 / 0.52), transparent 30%),
    color-mix(in oklch, var(--fruit-raspberry-light) 16%, var(--surface-solid) 28%);
  box-shadow:
    inset 4px 5px 7px oklch(1 0 0 / 0.46),
    inset -10px -12px 18px color-mix(in oklch, var(--fruit-raspberry-depth) 22%, transparent),
    0 28px 70px oklch(0.11 0.05 311 / 0.22);
  backdrop-filter: blur(22px) saturate(1.22);
  transition: opacity 170ms ease, transform 250ms cubic-bezier(0.2, 1.18, 0.25, 1), border-radius 220ms ease;
}

.gummy-dialog__popup::before {
  position: absolute;
  z-index: 3;
  top: 5px;
  right: 16%;
  left: 17%;
  height: 13px;
  border-radius: 50%;
  background: radial-gradient(ellipse at center, oklch(1 0 0 / 0.5), transparent 72%);
  content: "";
  pointer-events: none;
  transform: rotate(-0.7deg);
}

.gummy-dialog__popup:not(.gummy-dialog__popup--preview)[data-starting-style],
.gummy-dialog__popup:not(.gummy-dialog__popup--preview)[data-ending-style] {
  opacity: 0;
  transform: scaleX(0.94) scaleY(0.9) translateY(12px);
}

.gummy-dialog__popup:focus-visible {
  background:
    radial-gradient(ellipse at 78% 92%, color-mix(in oklch, var(--fruit-aqua-core) 42%, transparent), transparent 43%),
    radial-gradient(circle at 12% 8%, oklch(1 0 0 / 0.76) 0 2%, transparent 4%),
    color-mix(in oklch, var(--fruit-raspberry-core) 43%, transparent);
  box-shadow:
    inset 4px 5px 7px oklch(1 0 0 / 0.48),
    inset -10px -12px 18px color-mix(in oklch, var(--fruit-aqua-depth) 20%, transparent),
    0 28px 70px oklch(0.11 0.05 311 / 0.24);
}

.gummy-dialog__reservoir {
  position: absolute;
  z-index: 0;
  display: block;
  background:
    radial-gradient(circle at 34% 23%, oklch(1 0 0 / 0.7) 0 5%, transparent 7%),
    radial-gradient(ellipse at 50% 52%, var(--fruit-raspberry-core), color-mix(in oklch, var(--fruit-raspberry-rim) 72%, transparent) 62%, color-mix(in oklch, var(--fruit-raspberry-depth) 46%, transparent) 88%);
  box-shadow:
    inset 4px 5px 7px oklch(1 0 0 / 0.46),
    inset -8px -10px 14px color-mix(in oklch, var(--fruit-raspberry-depth) 32%, transparent);
}

.gummy-dialog__reservoir--start {
  top: -6px;
  left: -7px;
  width: 126px;
  height: 74px;
  border-radius: 54% 46% 58% 42% / 48% 58% 42% 52%;
  transform: rotate(-3deg);
}

.gummy-dialog__reservoir--end {
  right: -11px;
  bottom: -11px;
  width: 142px;
  height: 82px;
  border-radius: 58% 42% 54% 46% / 43% 57% 45% 55%;
  transform: rotate(3deg);
}

.gummy-dialog__plane {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 18px;
  min-height: 228px;
  padding: 32px 34px 30px;
  border-radius: 29px 25px 35px 23px / 24px 34px 22px 31px;
  background:
    radial-gradient(ellipse at 16% 6%, oklch(1 0 0 / 0.48), transparent 28%),
    color-mix(in oklch, var(--surface-solid) 78%, transparent);
  box-shadow:
    inset 3px 4px 8px oklch(1 0 0 / 0.34),
    inset -7px -8px 14px color-mix(in oklch, var(--fruit-raspberry-depth) 6%, transparent);
  backdrop-filter: blur(28px) saturate(1.14);
}

.gummy-dialog__title {
  margin: 0;
  padding-right: 44px;
  color: var(--ink);
  font-family: var(--font-display), sans-serif;
  font-size: clamp(25px, 4vw, 34px);
  font-weight: 780;
  letter-spacing: -0.04em;
  line-height: 1;
}

.gummy-dialog__description {
  margin: -7px 0 0;
  color: var(--ink-soft);
  font-size: 14px;
}

.gummy-dialog__close {
  border: 0;
  outline: none;
  cursor: pointer;
}

.gummy-dialog__close--icon {
  position: absolute;
  z-index: 2;
  top: 27px;
  right: 28px;
  display: grid;
  width: 38px;
  min-height: 38px;
  padding: 0;
  place-items: center;
  border-radius: 48% 52% 44% 56%;
  background:
    radial-gradient(circle at 32% 24%, oklch(1 0 0 / 0.62), transparent 26%),
    color-mix(in oklch, var(--fruit-raspberry-light) 52%, transparent);
  box-shadow:
    inset 2px 3px 4px oklch(1 0 0 / 0.44),
    inset -3px -4px 7px color-mix(in oklch, var(--fruit-raspberry-depth) 14%, transparent);
  color: var(--ink-soft);
  font-size: 20px;
  line-height: 1;
}

.gummy-dialog__close--icon:hover { transform: rotate(5deg) scale(1.04); }
.gummy-dialog__close--icon:focus-visible {
  background:
    radial-gradient(circle at 72% 78%, color-mix(in oklch, var(--fruit-aqua-rim) 58%, transparent), transparent 54%),
    color-mix(in oklch, var(--fruit-aqua-light) 66%, transparent);
  box-shadow: inset 0 -5px 0 color-mix(in oklch, var(--fruit-aqua-rim) 78%, transparent);
  color: oklch(0.225 0.068 309);
  transform: rotate(3deg) scaleX(1.05) scaleY(0.96);
}

.gummy-dialog__actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  margin-top: auto;
  padding-top: 12px;
}

.gummy-dialog__popup--preview {
  width: min(100%, 480px);
  box-shadow:
    inset 4px 5px 7px oklch(1 0 0 / 0.46),
    inset -10px -12px 18px color-mix(in oklch, var(--fruit-raspberry-depth) 22%, transparent);
}

:root[data-theme="dark"] .gummy-tabs__list {
  background:
    radial-gradient(ellipse at 11% 8%, oklch(1 0 0 / 0.22), transparent 20%),
    radial-gradient(ellipse at 86% 92%, color-mix(in oklch, var(--fruit-grape-core) 22%, transparent), transparent 40%),
    color-mix(in oklch, var(--surface-solid) 48%, transparent);
  box-shadow:
    inset 3px 3px 5px oklch(1 0 0 / 0.2),
    inset -7px -8px 13px color-mix(in oklch, var(--fruit-grape-depth) 18%, transparent),
    0 12px 27px oklch(0.08 0.035 311 / 0.2);
}

:root[data-theme="dark"] .gummy-dialog__trigger {
  background:
    radial-gradient(circle at 13% 14%, oklch(1 0 0 / 0.3) 0 2px, transparent 3px),
    radial-gradient(ellipse at 87% 82%, color-mix(in oklch, var(--fruit-raspberry-core) 35%, transparent), transparent 43%),
    linear-gradient(150deg, oklch(1 0 0 / 0.12), transparent 34%),
    color-mix(in oklch, var(--surface-solid) 48%, transparent);
  box-shadow:
    inset 2px 3px 5px oklch(1 0 0 / 0.18),
    inset 0 -8px 14px color-mix(in oklch, var(--fruit-raspberry-core) 18%, transparent);
}

:root[data-theme="dark"] .gummy-dialog__popup {
  background:
    radial-gradient(circle at 12% 8%, oklch(1 0 0 / 0.28) 0 2%, transparent 4%),
    radial-gradient(ellipse at 6% 4%, color-mix(in oklch, var(--fruit-raspberry-core) 54%, transparent), transparent 31%),
    radial-gradient(ellipse at 94% 94%, color-mix(in oklch, var(--fruit-raspberry-core) 48%, transparent), transparent 40%),
    color-mix(in oklch, var(--surface-solid) 48%, transparent);
  box-shadow:
    inset 4px 5px 7px oklch(1 0 0 / 0.18),
    inset -10px -12px 18px color-mix(in oklch, var(--fruit-raspberry-depth) 32%, transparent),
    0 30px 74px oklch(0.06 0.035 311 / 0.42);
}

:root[data-theme="dark"] .gummy-menu__trigger {
  background:
    radial-gradient(circle at 13% 14%, oklch(1 0 0 / 0.34) 0 2px, transparent 3px),
    radial-gradient(ellipse at 91% 72%, color-mix(in oklch, var(--fruit-grape-core) 38%, transparent), transparent 43%),
    linear-gradient(150deg, oklch(1 0 0 / 0.12), transparent 34%),
    color-mix(in oklch, var(--surface-solid) 50%, transparent);
  box-shadow:
    inset 2px 2px 3px oklch(1 0 0 / 0.2),
    inset 0 -7px 13px color-mix(in oklch, var(--fruit-grape-core) 20%, transparent);
  color: var(--ink);
}

:root[data-theme="dark"] .gummy-menu__popup {
  background: transparent;
  box-shadow: none;
}

:root[data-theme="dark"] .gummy-tabs__tab[data-active] { color: oklch(0.225 0.068 309); }

:root[data-theme="dark"] .gummy-menu__reading-plane,
:root[data-theme="dark"] .gummy-dialog__plane {
  background:
    radial-gradient(ellipse at 16% 6%, oklch(1 0 0 / 0.13), transparent 29%),
    color-mix(in oklch, var(--surface-solid) 67%, transparent);
}

:root[data-theme="dark"] .gummy-menu__item[data-highlighted] {
  color: var(--ink);
}

:root[data-theme="dark"] .gummy-menu__reading-plane {
  background:
    radial-gradient(ellipse at 91% 90%, color-mix(in oklch, var(--fruit-grape-core) 42%, transparent), color-mix(in oklch, var(--fruit-grape-rim) 18%, transparent) 34%, transparent 62%),
    radial-gradient(ellipse at 10% 7%, oklch(1 0 0 / 0.16), transparent 30%),
    color-mix(in oklch, var(--surface-solid) 58%, transparent);
  box-shadow:
    inset 3px 3px 5px oklch(1 0 0 / 0.16),
    inset -11px -12px 20px color-mix(in oklch, var(--fruit-grape-core) 18%, transparent),
    0 18px 40px oklch(0.08 0.035 311 / 0.25);
}

:root[data-theme="dark"] .gummy-menu__reading-plane::before {
  background: color-mix(in oklch, var(--surface-solid) 72%, transparent);
}

:root[data-theme="dark"] .gummy-menu__reading-plane::after {
  background: color-mix(in oklch, var(--fruit-grape-core) 27%, var(--surface-solid) 38%);
}

:root[data-theme="dark"] .gummy-menu__item-state {
  color: var(--fruit-raspberry-light);
}

:root[data-theme="dark"] .gummy-menu__item[data-tone="danger"],
:root[data-theme="dark"] .gummy-menu__item[data-tone="danger"] .gummy-menu__item-icon {
  color: oklch(0.82 0.13 10);
}

@media (max-width: 620px) {
  .gummy-badge__label {
    overflow-wrap: anywhere;
    white-space: normal;
  }
  .gummy-input__adornment { font-size: 10px; }
  .gummy-tabs__tab { padding-inline: 10px; font-size: 12px; }
  .gummy-dialog__plane { min-height: 240px; padding: 28px 22px 24px; }
  .gummy-dialog__actions { align-items: stretch; flex-direction: column-reverse; }
  .gummy-dialog__actions .gummy-button { width: 100%; }
  .gummy-dialog__close--icon { top: 19px; right: 18px; }
}

@media (prefers-reduced-motion: reduce) {

  .gummy-card--interactive:focus-visible,
.gummy-card--preview-focus,
.gummy-card--interactive:hover,
.gummy-card--interactive:active,
.gummy-input__control:has(.gummy-input__field:focus-visible),
.gummy-input--preview-focus .gummy-input__control,
.gummy-input__control {
    transform: none;
  }

  .gummy-badge,
.gummy-badge::before,
.gummy-badge::after,
.gummy-card__frame,
.gummy-card__frame-reservoir {
    animation: none !important;
    filter: none;
    transform: none;
  }

  .gummy-tabs__indicator,
.gummy-menu__popup,
.gummy-dialog__popup {
    animation: none !important;
    transform: none;
  }
}
